// ================= PRODUCT MEDIA, PAGE, PREVIEW, AI COPY & SEO =================
const LOGO_URI = 'data:image/png;base64,';
const ICON_URI = 'data:image/png;base64,';
const brandInit = () => { ['navLogo','footLogo'].forEach(id => { const e = document.getElementById(id); if (e) e.src = id === 'navLogo' ? ICON_URI : LOGO_URI; }); };
if (document.readyState !== 'loading') brandInit(); else document.addEventListener('DOMContentLoaded', brandInit);
const BRAND = () => db.settings.businessName || 'Anitha Pemmasani';
const cap = s => String(s || '').replace(/^./, c => c.toUpperCase());
const uniqCI = arr => { const seen = new Set(); return arr.filter(x => { const k = String(x).toLowerCase(); if (!x || seen.has(k)) return false; seen.add(k); return true; }); };
function slugify(s) { return String(s || '').toLowerCase().normalize('NFKD').replace(/[^\w\s-]/g, '').trim().replace(/[\s_]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 80); }
function uniqueSlug(base, id) { const s = slugify(base) || 'product'; let out = s, n = 2; while (db.products.some(p => p.slug === out && p.id !== id)) out = `${s}-${n++}`; return out; }
function fitText(t, max) {
  t = String(t || '').replace(/\s+/g, ' ').trim(); if (t.length <= max) return t;
  const cut = t.slice(0, max - 1), sp = cut.lastIndexOf(' ');
  return (sp > max * 0.6 ? cut.slice(0, sp) : cut).replace(/[\s,;:–|-]+$/, '') + '…';
}
function draftImages(d) { return d.images && d.images.length ? d.images : (d.image ? [d.image] : []); }
function catFromSku(sku) { const code = String(sku || '').split('-')[1]; const n = (SKU_CATEGORIES.find(c => c[0] === code) || [])[1]; return db.categories.includes(n) ? n : null; }
function cleanName(file) { return String(file || '').replace(/\.[^/.]+$/, '').replace(/[_-]+/g, ' ').replace(/[\s]*\(?\d+\)?$/, '').replace(/\s+/g, ' ').trim(); }

// ---- video links: YouTube / Vimeo / direct file ----
function videoInfo(url) {
  url = String(url || '').trim(); if (!url) return null;
  let u; try { u = new URL(url); } catch (e) { return { error: 'Enter a full link starting with https://' }; }
  if (!/^https?:$/.test(u.protocol)) return { error: 'Enter a full link starting with https://' };
  const h = u.hostname.replace(/^www\./, ''); let id = '', m;
  if (h === 'youtu.be') id = u.pathname.slice(1).split('/')[0];
  else if (h.endsWith('youtube.com')) id = u.searchParams.get('v') || ((m = u.pathname.match(/\/(?:embed|shorts|live)\/([\w-]{6,})/)) ? m[1] : '');
  if (id && /^[\w-]{6,15}$/.test(id)) return { type: 'youtube', embed: `https://www.youtube-nocookie.com/embed/${id}`, thumb: `https://img.youtube.com/vi/${id}/hqdefault.jpg`, label: 'YouTube video', url };
  if (h === 'vimeo.com' || h.endsWith('.vimeo.com')) { m = u.pathname.match(/(\d{5,})/); if (m) return { type: 'vimeo', embed: `https://player.vimeo.com/video/${m[1]}`, label: 'Vimeo video', url }; }
  if (/\.(mp4|webm|ogg|mov)$/i.test(u.pathname)) return { type: 'file', src: url, label: 'Video file', url };
  return { error: 'Use a YouTube, Vimeo or direct .mp4 / .webm link' };
}
function productMedia(p) {
  const imgs = (p.images && p.images.length ? p.images : (p.image ? [p.image] : [])).map(src => ({ type: 'img', src }));
  const vi = videoInfo(p.video); if (vi && !vi.error) imgs.push({ type: 'video', info: vi });
  return imgs;
}
function mediaHTML(m, alt) {
  if (!m) return `<div class="main-img" style="display:flex;align-items:center;justify-content:center;color:#6b6862;">No photo</div>`;
  if (m.type === 'img') return `<img class="main-img" src="${esc(m.src)}" alt="${esc(alt)}" decoding="async">`;
  const i = m.info;
  if (i.type === 'file') return `<video class="main-img" src="${esc(i.src)}" controls playsinline preload="metadata" style="background:#000;"></video>`;
  return `<div class="vid-wrap"><iframe src="${esc(i.embed)}" title="${esc(alt)} video" loading="lazy" allow="accelerometer; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe></div>`;
}
const GALS = {};
function galleryHTML(p, gk) {
  const media = productMedia(p), alt = p.altText || p.name; GALS[gk] = { media, alt };
  return `<div class="gal" id="${gk}"><div id="${gk}-main">${mediaHTML(media[0], alt + ' – photo 1')}</div>${media.length > 1 ? `<div class="gal-thumbs">${media.map((m, i) => `<div class="gal-thumb ${i === 0 ? 'active' : ''}" onclick="galSelect('${gk}',${i})" title="${m.type === 'img' ? 'Photo ' + (i + 1) : 'Video'}">${m.type === 'img' ? `<img src="${esc(m.src)}" alt="${esc(alt)} – thumbnail ${i + 1}" loading="lazy">` : `<div class="gal-play">▶<small>Video</small></div>`}</div>`).join('')}</div>` : ''}</div>`;
}
let GAL_TOUCH = null;
document.addEventListener('touchstart', e => { const g = e.target.closest && e.target.closest('.gal'); GAL_TOUCH = g && e.touches.length === 1 ? { id: g.id, x: e.touches[0].clientX, y: e.touches[0].clientY } : null; }, { passive: true });
document.addEventListener('touchend', e => {
  const t = GAL_TOUCH; GAL_TOUCH = null; if (!t || !GALS[t.id]) return; const c = e.changedTouches[0], dx = c.clientX - t.x, dy = c.clientY - t.y;
  if (Math.abs(dx) < 45 || Math.abs(dx) < Math.abs(dy) * 1.5) return;
  const act = [...document.querySelectorAll(`#${t.id} .gal-thumb`)].findIndex(x => x.classList.contains('active')), n = GALS[t.id].media.length, from = act < 0 ? 0 : act;
  galSelect(t.id, (from + (dx < 0 ? 1 : -1) + n) % n);
}, { passive: true });
function galSelect(gk, i) {
  const g = GALS[gk]; if (!g) return;
  const main = document.getElementById(gk + '-main'); if (main) main.innerHTML = mediaHTML(g.media[i], `${g.alt} – photo ${i + 1}`);
  document.querySelectorAll(`#${gk} .gal-thumb`).forEach((t, k) => t.classList.toggle('active', k === i));
}
function tagChips(tags) { return (tags && tags.length) ? `<div class="chips">${tags.map(t => `<span class="chip ro">${esc(t)}</span>`).join('')}</div>` : ''; }
function productPageHTML(p, gk, opts = {}) {
  const inStock = p.stock > 0;
  return `<div class="detail-grid"><div class="detail-gallery">${galleryHTML(p, gk)}</div><div class="detail-info">
    <div class="detail-cat">${esc(p.category)}</div>
    <h2 class="detail-name">${esc(p.name || 'Untitled product')}</h2>
    <div class="detail-price">${p.price ? '₹ ' + money(p.price) : '<span style="color:#6b6862;font-size:16px;">Price not set</span>'}</div>${pageExtrasHTML(p, gk, opts)}
    ${p.reviews > 0 ? `<a class="rv-link" onclick="var r=document.getElementById('rv-root');if(r)r.scrollIntoView({behavior:'smooth'})">${starsHTML(p.rating)} <span>${p.rating} · ${p.reviews} review${p.reviews > 1 ? 's' : ''}</span></a>` : ''}
    <p class="detail-desc">${esc(p.description || 'No description yet.')}</p>
    ${tagChips(p.tags)}
    <div class="tab-content active"><ul style="margin-top:14px;"><li><strong>SKU:</strong> ${esc(p.sku)}</li><li><strong>Availability:</strong> ${inStock ? (oneOfAKind(p) ? 'One of a kind' : p.stock <= 2 ? `Only ${p.stock} left` : 'In stock') : 'Sold out'}</li><li><strong>Category:</strong> ${esc(p.category)}</li>${p.rating ? `<li><strong>Rating:</strong> ${p.rating} (${p.reviews} reviews)</li>` : ''}</ul></div>
    ${deliveryWidgetHTML(p, gk, opts.preview)}${shipNoteHTML()}
    ${!inStock && !opts.preview ? `<button class="btn-full buy-btn" style="margin-bottom:10px;" onclick="openStockAlert('${p.id}')">${notifyLabel(p.id)}${myAlert(p.id) ? '' : ' when it is back'}</button>${isAccessory(p) ? '' : `<button class="btn-outline similar-btn" style="margin:0 0 10px;" onclick="openSimilarAlert('${p.id}')">${mySimilar(p.id) ? '✨ You will hear about similar sarees' : '✨ Tell me about similar sarees'}</button><button class="btn-outline request-btn" style="margin:0 0 10px;" onclick="openSimilarRequest('${p.id}')">💬 Request a similar piece</button>`}` : `<button class="btn-full buy-btn" style="margin-bottom:10px;" ${opts.preview ? 'disabled' : `onclick="addToCart('${p.id}');closeModal('productModal');"`}>Add to Cart</button>`}
    <button class="btn-outline" style="margin-top:0;" ${opts.preview ? 'disabled' : `onclick="openShare('${p.id}')"`}>🔗 Share this saree</button>${giftButtonHTML(p, opts.preview)}${waChatButtonHTML(p, opts.preview)}
  </div></div>`;
}

// The shop's current announcement (for example the free-shipping line) is also shown on every product page.
function shipNoteHTML() { const a = db.home && activeAnnouncements()[0]; return a ? `<div class="ship-note" role="note">🚚 ${esc(a.text).replace(/ · /g, ' <span>·</span> ')}</div>` : ''; }
// ---- preview (product page / shop card / search result, desktop or mobile) ----
const PV = { p: null, tab: 'page', device: 'desktop' };
function openPreview(p) { PV.p = p; PV.tab = 'page'; renderPreview(); gid_('previewModal').classList.add('active'); }
function gid_(id) { return document.getElementById(id); }
function pvSet(k, v) { PV[k] = v; renderPreview(); }
function renderPreview() {
  const p = PV.p, mob = PV.device === 'mobile';
  const tabs = [['page', '🛍️ Product page'], ['card', '🗂️ Shop grid'], ['search', '🔎 Google & sharing'], ['ig', '📸 Instagram'], ['wa', '💬 WhatsApp status']];
  let body = '';
  if (PV.tab === 'page') body = `<div class="pv-frame ${mob ? 'pv-mobile' : ''}">${productPageHTML(p, 'pv-gal', { preview: true })}</div>`;
  else if (PV.tab === 'ig' || PV.tab === 'wa') { const im = (p.images || [p.image])[0] || '', lc = (() => { try { const k = packLocal(p); return k.en.caption + '\n\n' + k.en.hashtags.slice(0, 5).map(h => '#' + h).join(' '); } catch (e) { return p.name || ''; } })(); body = (PV.tab === 'ig' ? pvIgHTML({ img: im, caption: lc }) : pvWaHTML({ img: im, caption: lc })) + '<p class="note" style="text-align:center;">Caption shown is a draft; you finish it in <b>📸 Share on Instagram</b>.</p>'; }
  else if (PV.tab === 'card') {
    const others = db.products.filter(x => x.id !== p.id).slice(0, 2);
    body = `<div class="pv-frame pv-noclick ${mob ? 'pv-mobile' : ''}"><div class="pv-grid ${mob ? 'one' : ''}">${[p, ...others].map((x, i) => `<div style="${i === 0 ? 'outline:3px solid var(--gold);outline-offset:3px;border-radius:4px;' : 'opacity:.55;'}">${productCardHTML(x)}</div>`).join('')}</div></div><p class="note" style="text-align:center;">Highlighted card is the new product, shown next to existing ones.</p>`;
  } else {
    const t = p.seoTitle || `${p.name} | ${BRAND()}`, m = p.metaDescription || fitText(p.description, 155), host = (db.settings.siteUrl || 'https://yourstore.com').replace(/^https?:\/\//, '').replace(/\/$/, '');
    const og = (p.images || [])[0] || p.image || '';
    body = `<div class="pv-serp-wrap"><h4>Google search result</h4><div class="serp"><div class="serp-url">${esc(host)} › product › ${esc(p.slug || slugify(p.name))}</div><div class="serp-title">${esc(t)}</div><div class="serp-desc">${esc(m)}</div></div>
      <h4 style="margin-top:22px;">Link shared on WhatsApp / Facebook</h4><div class="og-card">${og ? `<img src="${esc(og)}" alt="">` : ''}<div class="og-body"><div class="og-host">${esc(host.toUpperCase())}</div><div class="og-title">${esc(fitText(t, 70))}</div><div class="og-desc">${esc(fitText(m, 110))}</div></div></div></div>`;
  }
  gid_('previewBody').innerHTML = `<div class="pv-bar"><div class="pv-tabs">${tabs.map(([k, l]) => `<button class="${PV.tab === k ? 'active' : ''}" onclick="pvSet('tab','${k}')">${l}</button>`).join('')}</div>${PV.tab !== 'search' && PV.tab !== 'ig' && PV.tab !== 'wa' ? `<div class="pv-tabs"><button class="${!mob ? 'active' : ''}" onclick="pvSet('device','desktop')">🖥 Desktop</button><button class="${mob ? 'active' : ''}" onclick="pvSet('device','mobile')">📱 Mobile</button></div>` : ''}</div>${body}`;
}
function closePreviewModal() { gid_('previewModal').classList.remove('active'); }
function previewDraft(i) { const d = db.drafts[i]; if (d) openPreview(draftToProduct(d)); }
function draftToProduct(d) {
  const imgs = draftImages(d);
  return { id: 'draft-' + d.id, name: d.name || 'Untitled product', sku: d.sku, category: d.category || catFromSku(d.sku) || db.categories[0] || '', price: d.price || 0, stock: 1, images: imgs, image: imgs[0], video: d.video || '', description: d.description || '', tags: d.tags || [], seoTitle: d.seoTitle || '', metaDescription: d.metaDescription || '', slug: d.slug || slugify(d.name || d.sku), altText: d.altText || '' };
}

// ---- AI-assisted copy: category knowledge + colours detected from the photo (+ optional AI endpoint) ----
const COLOR_NAMES = [['Maroon', 128, 0, 32], ['Wine', 114, 47, 55], ['Red', 200, 30, 40], ['Rust', 183, 65, 14], ['Orange', 235, 120, 30], ['Mustard', 225, 173, 1], ['Yellow', 245, 215, 40], ['Gold', 212, 175, 55], ['Cream', 245, 235, 210], ['Ivory', 250, 247, 235], ['Beige', 222, 200, 165], ['Olive', 110, 120, 50], ['Green', 40, 140, 60], ['Emerald Green', 0, 110, 80], ['Mint', 170, 225, 200], ['Teal', 0, 128, 128], ['Peacock Blue', 0, 95, 115], ['Turquoise', 64, 200, 190], ['Sky Blue', 135, 190, 235], ['Blue', 40, 90, 190], ['Navy', 20, 30, 90], ['Lavender', 190, 170, 230], ['Purple', 110, 50, 150], ['Magenta', 190, 20, 120], ['Pink', 240, 130, 170], ['Peach', 255, 200, 170], ['Coral', 245, 110, 95], ['Brown', 110, 70, 40], ['Grey', 130, 130, 130], ['Black', 25, 25, 25], ['White', 252, 252, 252]];
function nearestColour(r, g, b) { let best = '', bd = 1e9; for (const [n, cr, cg, cb] of COLOR_NAMES) { const d = (r - cr) ** 2 * 0.3 + (g - cg) ** 2 * 0.59 + (b - cb) ** 2 * 0.11; if (d < bd) { bd = d; best = n; } } return best; }
async function dominantColours(src, n = 2) {
  try {
    const img = await new Promise((res, rej) => { const i = new Image(); i.crossOrigin = 'anonymous'; i.onload = () => res(i); i.onerror = rej; i.src = src; });
    const c = document.createElement('canvas'); c.width = c.height = 40; const x = c.getContext('2d'); x.drawImage(img, 0, 0, 40, 40);
    const d = x.getImageData(0, 0, 40, 40).data, count = {}; let total = 0;
    for (let i = 0; i < d.length; i += 4) { if (d[i + 3] < 128) continue; const nm = nearestColour(d[i], d[i + 1], d[i + 2]); count[nm] = (count[nm] || 0) + 1; total++; }
    const neutral = new Set(['White', 'Ivory', 'Cream', 'Beige', 'Grey', 'Black']);
    const ranked = Object.entries(count).filter(([, v]) => v / total >= 0.06).sort((a, b) => b[1] - a[1]).map(e => e[0]);
    return [...ranked.filter(k => !neutral.has(k)), ...ranked.filter(k => neutral.has(k))].slice(0, n);
  } catch (e) { return []; }
}
