  'Tussar': { fabric: 'pure Tussar silk', origin: 'the weaving clusters of Bhagalpur and Jharkhand', note: 'a naturally textured weave with a soft, matte golden sheen', occ: ['Festive', 'Wedding', 'Party', 'Office'], care: 'Dry clean recommended. If hand washing, use cold water with a mild detergent and dry in shade.', kw: ['Tussar Silk Saree', 'Tussar Saree Online', 'Pure Tussar Silk'], silk: true },
  'Maheswari': { fabric: 'Maheshwari silk', origin: 'Maheshwar in Madhya Pradesh', note: 'a feather-light drape with the signature reversible border', occ: ['Office', 'Festive', 'Party', 'Casual'], care: 'Dry clean first. Wash gently in cold water, never wring, and dry in shade.', kw: ['Maheshwari Saree', 'Maheshwari Silk Saree', 'Lightweight Silk Saree'], silk: true },
