  const imgs = p.images.map((_, i) => imgPath(i)), url = `${base}/product/${p.slug}.html`, title = p.seoTitle || `${p.name} | ${BRAND()}`, desc = p.metaDescription || fitText(p.description, 155);
  const ld = JSON.stringify(productLd(p, base, imgs)).replace(/</g, '\\u003c'), vi = videoInfo(p.video);
  const para = String(p.description || '').split(/\n{2,}/).map(b => b.startsWith('Highlights') ? `<ul>${b.split('\n').slice(1).filter(l => l.trim()).map(l => `<li>${esc(l.replace(/^•\s*/, ''))}</li>`).join('')}</ul>` : `<p>${esc(b).replace(/\n/g, '<br>')}</p>`).join('\n');
