  files.push({ path: 'terms.html', text: legalStaticPage('terms', base) }, { path: 'privacy.html', text: legalStaticPage('privacy', base) });
  files.push({ path: 'products.json', text: JSON.stringify(db.products.map(p => productLd(p, base, p.images.map((s, i) => /^data:/.test(s) ? `${base}/images/${p.slug}-${i + 1}.jpg` : s))), null, 2) });
