async function downloadSeoPack() {
  if (!db.products.length) { showToast('No products yet', 'error'); return; }
  const files = buildSeoPack();
  if (!window.JSZip) { saveBlob(new Blob([files[0].text], { type: 'application/xml' }), 'sitemap.xml'); setTimeout(() => saveBlob(new Blob([files[1].text], { type: 'text/plain' }), 'robots.txt'), 300); showToast('ZIP library unavailable offline – downloaded sitemap.xml and robots.txt only', 'error'); return; }
  const zip = new JSZip();
  files.forEach(f => zip.file(f.path, f.blob ? f.blob() : f.text));
  saveBlob(await zip.generateAsync({ type: 'blob' }), `seo-pack-${ymd(new Date())}.zip`);
  showToast(`✅ SEO pack downloaded (${db.products.length} product pages)`, 'success');
}
function downloadSitemap() { saveBlob(new Blob([buildSitemap(siteBase() || 'https://www.example.com')], { type: 'application/xml' }), 'sitemap.xml'); }
